namespace LunaArc.Studio.Models;

public sealed record HelpTopic(string Id, string Title, string Body, HelpTopic[] Children, string[] RelatedIds)
{
    public override string ToString() => Title;
}

public static class HelpCatalog
{
    private static HelpTopic Page(string id, string title, string body, params string[] related) => new(id, title, body, [], related);
    private static HelpTopic Section(string id, string title, string body, params HelpTopic[] children) => new(id, title, body, children, children.Select(c => c.Id).ToArray());
    public static IReadOnlyList<HelpTopic> Contents { get; } = new[]
    {
        Section("welcome", "About LunaArc", "LunaArc is an archive manager for Windows and Linux. Browse, create, extract and test archives using the desktop interface or command-line tool.\n\nChoose a topic on the left, search for a word, or follow a related topic below. This guide is included with the application and works offline.",
            Page("overview", "What is LunaArc?", "LunaArc combines an archive browser, safe extraction controls and archive creation tools. It creates LARC, ZIP, TAR GZip and 7z archives. Password-protected TAR GZip is wrapped inside encrypted 7z.\n\nIt can read ZIP, RAR, 7z, TAR/TAR GZip and its own LARC format. It does not create RAR archives or edit entries in an existing archive. Other formats depend on the archive reader and are not all verified.", "create", "extract", "limits"),
            Page("quick-start", "Quick start", "OPEN: choose Open or press Ctrl+O, then select an archive. Double-click folders to navigate and use Up to return.\n\nCREATE: choose Add, select source files, enter an unused output name, choose a format and press OK.\n\nEXTRACT: open an archive and choose Extract To, or right-click an archive in the file manager and choose a LunaArc extraction command.\n\nTEST: choose Test to check archive contents before using them. Testing detects supported integrity failures; it is not a malware scan.", "create", "extract", "test"),
            Page("limits", "Supported formats and limitations", "Creation: LARC, ZIP, TAR GZip and 7z. New password-protected LARC uses authenticated v2; older LunaArc versions cannot read it. Existing v1 archives remain readable. RAR creation and archive-entry editing are unavailable.\n\nEncrypted ZIP: WinZip AES-256; names remain visible. ZIP64 supports large files and more than 65,535 entries. Native split ZIP disks remain unsupported; LunaArc split sets with a manifest are supported.\n\nTAR GZip encryption produces .tar.gz.7z and is automatically expanded in one operation by LunaArc 2.3+. Source deletion is unavailable for that wrapper.\n\nLunaArc split sets open from .001 with every numbered part and the .lunasplit.json manifest in the same folder. Native split ZIP/RAR volumes are not implemented. TAR Zstandard creation is unsupported. LARC payloads stream through bounded buffers; metadata and high compression presets still require additional memory. A successful build does not guarantee support for every archive variant.", "passwords", "wrapped-tar", "solid")),
        Section("archive-guide", "Creating archives", "Use Add or the file-manager compression menu to open Archive name and parameters. All creation options are on General.",
            Page("create", "Archive name and parameters", "1. Select files or a folder using Add or a right-click compression command.\n2. Enter a new archive path or choose Browse. Save outside selected source folders. Existing archives are preserved; choose another name if the destination exists.\n3. Choose LARC, ZIP, TAR GZip or 7z and a compression method from Store through Best.\n4. Optionally set a password, archive comment or supported archiving options.\n5. Press OK. Cancel discards the draft.\n\nToolbar Add opens the completed archive in the browser. Right-click creation uses only options and compact progress windows and exits after success.", "passwords", "solid", "source-deletion"),
            Page("passwords", "Passwords and encryption", "Set password opens masked password and confirmation fields. Enter matching values. Show password reveals them; leave both blank to remove the password.\n\nNew password-protected LARC uses v2 AES-256-GCM, authenticating names and contents. LunaArc 2.1 and older cannot read v2; existing v1 archives remain readable. Opening v2 needs a full authentication pass and temporary plaintext archive space. Legacy v1 CBC has no authentication.\n\nZIP uses WinZip AES-256 for contents; file names remain visible. Use a compatible reader such as 7-Zip or WinRAR.\n\n7z uses AES-256 and encrypts file names. 7z passwords support Unicode, up to 1024 characters, excluding line breaks and NUL.\n\nTAR GZip has no native password encryption. With a password, LunaArc creates .tar.gz.7z. Use a strong password and keep a separate backup; recovery cannot guarantee finding a forgotten password.", "wrapped-tar", "recovery-password", "limits"),
            Page("split", "Split archives into volumes", "In Create > General, enter a whole size in MiB under Split to volumes; leave it blank for one archive. Keep all .001/.002 numbered parts and the .lunasplit.json manifest in the same directory. Open .001 to automatically assemble, verify and extract. Missing parts, altered checksums and unsafe paths fail before extraction. Assembly requires temporary disk space. SFX, recovery, locks and source deletion cannot combine with splitting. These are LunaArc sets, not native split ZIP or RAR volumes.", "create", "extract", "passwords"),
            Page("progress-space", "Progress and free space", "LunaArc estimates temporary and destination disk requirements before shared creation and staged reads/extraction. Requirements on one volume are combined with a reserve. Estimates are conservative and do not reserve space; quotas, concurrent disk use and unavailable queries still rely on I/O errors.\n\nProgress names the current phase. Byte phases show measured speed and a per-phase ETA after warm-up; pause time is excluded. External encoder steps without known progress show an indeterminate bar. Item counts are not byte throughput.\n\nExplicit .tar.gz.7z wrappers automatically expose/extract final TAR contents after one password entry. Keep the original archive name, or the EncryptedTarGz SFX/split metadata, to retain automatic recognition.", "create", "extract", "wrapped-tar"),
            Page("wrapped-tar", "Encrypted TAR GZip (.tar.gz.7z)", "Selecting TAR GZip and setting a password changes the output to .tar.gz.7z. It is a standard encrypted 7z containing one ordinary TAR GZip file.\n\nLunaArc 2.3+ automatically opens the outer 7z with the password, verifies its one root TAR GZip, then extracts the final contents. Enter the password once. Generic 7z containers are not recursively expanded. Removing the password before creation restores ordinary .tar.gz output.\n\nSource deletion, solid mode and comments are unavailable for this wrapper. LunaArc volume splitting is available after creation. Creating it needs temporary disk space for a plaintext inner TAR GZip; staging is removed when the operation finishes or fails.", "passwords", "extract", "source-deletion"),
            Page("solid", "Solid compression and comments", "Create solid archive is available for 7z only. Solid LZMA2 shares compression history across files and can improve compression for similar data. It needs the packaged 7-Zip encoder and staging space. Pause applies before and after encoding; Cancel stops the encoder.\n\nCompression method maps Store through Best to format-specific settings. Higher settings may need more time or memory; results depend on the source data.\n\nArchive comments are supported for LARC and ZIP. TAR GZip and 7z comments are unavailable.", "create", "sfx", "limits"),
            Page("source-deletion", "Delete files after archiving", "This option is off by default for each creation. Enable it only when you intend to remove archived originals. It forces archive testing and content comparison before deleting matching files and represented empty folders.\n\nChanged or new source files are kept. Links, filesystem roots and overlapping sources cannot be deleted automatically. Verification needs temporary extraction space. Cleanup results stay visible for acknowledgement in right-click sessions.\n\nThe encrypted TAR GZip wrapper disables this option because it contains another archive. Keep a separate backup of important files.", "create", "test", "wrapped-tar")),
        Section("extract-guide", "Extracting and browsing", "Open an archive to browse its contents, or use a right-click extraction command for a standalone session.",
            Page("extract", "Extraction path and options", "Choose Extract To or right-click > Extract files... to select a destination. Browse and the folder tree select folders; New folder creates a folder inside the destination. Missing destination folders are created when extraction needs them.\n\nLong destination paths have a compact preview. Focus the field to edit the full path; its tooltip also shows the full path.\n\nThe Password tab appears only when encryption is detected. Enter the archive password there. An already unlocked browser session can reuse its current password.\n\nUpdate mode chooses eligible files first. Overwrite mode then handles conflicts. Existing files are skipped by default.", "update-mode", "overwrite", "miscellaneous"),
            Page("update-mode", "Update mode", "Extract and replace files: include all archive files, subject to the overwrite choice.\n\nExtract and update files: add missing files and update eligible older destination files.\n\nFreshen existing files only: update eligible older files that already exist; do not add missing files.\n\nEqual/newer destination files and existing files without a usable archive timestamp are preserved by the last two modes. Select Ask or Overwrite if you want eligible conflicts replaced; Skip still preserves them.", "overwrite", "extract"),
            Page("overwrite", "Overwrite mode", "Ask before overwrite: decide for each conflicting file.\n\nOverwrite without prompt: replace eligible existing files. Select this only when replacement is intended.\n\nSkip existing files: preserve existing files; this is the default in extraction options and shell sessions.\n\nRename automatically: keep both copies using a new destination name.\n\nUpdate mode is evaluated first. Extraction failures preserve an existing destination rather than replacing it with failed content.", "update-mode", "miscellaneous"),
            Page("miscellaneous", "Miscellaneous extraction options", "Keep broken files retains available failed output under a unique .broken name for ZIP, LARC and SharpCompress extraction. It does not apply to TAR or cancellation. The existing destination is preserved on failure.\n\nDisplay files after extraction opens the system file manager only after successful extraction. It does not run extracted files.\n\nThe compact progress window supports Pause/Resume and Cancel. Closing it during work requests cancellation and waits for the worker. Successful/cancelled shell sessions exit; errors remain visible until closed.", "extract", "test", "shell"),
            Page("test", "Test, preview and find", "Test checks supported archive integrity and declared sizes. Encrypted ZIP authentication is checked before extraction/testing. A successful test does not mean a file is safe to execute.\n\nView extracts a selected file into an isolated temporary preview directory. Editing that preview does not save changes back into the archive.\n\nFind or F3 filters names in the current folder. It does not change the archive. Double-click a folder to enter it, and Up returns to its parent. Info displays archive information and available comments.", "extract", "passwords", "limits")),
        Section("integration", "Shell and advanced tools", "These tools use LunaArc's own supported formats and companions. They do not create WinRAR/RAR recovery records.",
            Page("shell", "File-manager right-click commands", "Open with LunaArc opens the archive browser. Extract files... opens standalone extraction options. Extract Here uses the parent folder; Extract to folder uses an archive-named folder. Encrypted archives also request a password.\n\nAdd to archive... and Add to ZIP archive... open standalone General options and compact compression progress. These operations do not open a browser window behind them or open the result afterwards.\n\nWindows has classic menus and an optional Windows 11 menu package. Classic commands may appear under Show more options. On Windows 11, choose Tools > Enable Windows 11 right-click menu... and confirm the certificate trust prompt to enable the main menu. Interactive Setup and InstallContextMenu.cmd also offer this option. A complete published Windows package is required. Cancel keeps the classic menu; Windows may request administrator permission for certificate import. Reopen Explorer windows after enabling the menu. Linux provides a desktop launcher and Nautilus scripts, not Dolphin integration. Only one selected file/folder is supported.", "create", "extract", "sfx"),
            Page("sfx", "Self-extracting archives (SFX)", "Create SFX archive embeds a self-contained LunaArc extractor for the current OS and architecture. It requires a published package and adds roughly the executable's size. The result is .exe on Windows or .run on Linux.\n\nRecipients need no installed LunaArc or external encoder, but Linux GUI system libraries still apply. Downloaded Linux executables may need executable permission.\n\nGUI SFX opens standalone extraction options and progress. It never automatically runs extracted files. SHA-256 validates the embedded payload, but it is not a publisher signature. Only run executables from a trusted sender.", "create", "passwords", "limits"),
            Page("repair", "Recovery record and repair", "Add recovery record writes an .lrec companion. Keep it beside the exact archive. Tools > Repair archive using .lrec... verifies the record and saves repaired data to a new output, preserving the damaged original.\n\nThe record can recover one damaged or missing 1 MiB block per group of 16. Two damaged blocks in one group exceed its capacity. Insertion/deletion that shifts bytes may also exceed capacity. Final repair must match the original SHA-256.\n\nThe record costs about 6.25% plus block hashes and rounding; small archives need at least a 1 MiB parity block. This is not a RAR or PAR2 recovery record, and hashes do not authenticate the sender.", "lock", "test"),
            Page("lock", "Lock and unlock archives", "Lock archive writes a .lunalock companion and sets a read-only attribute. Keep the companion beside the archive; rename or move both together.\n\nTools > Unlock current archive explicitly removes the companion and clears read-only. Reading/extracting remains available while locked.\n\nThis is advisory protection in LunaArc, not encryption or access control. Other applications can remove the companion or change attributes. Creation still requires a new output name after unlocking.", "passwords", "repair"),
            Page("recovery-password", "Password recovery and vault", "Tools > Recover password searches an explicit candidate list or bounded mask. It does not bypass encryption or guarantee recovery. Searches are limited to one million candidates with at most two workers. Pause applies between attempts; Cancel stops the search.\n\nA result is verified against decrypted contents, not merely a readable catalog. The recovered password applies to the current archive session.\n\nThe password vault uses authenticated AES-256-GCM encryption and a master password. The master password is not stored. Legacy plaintext JSON is not imported automatically. Use synthetic passwords for testing and do not put secrets in logs.", "passwords", "extract"),
            Page("cli", "Command-line interface", "The published luna-cli shares the archive backend. Run luna-cli help for the command list. Quote paths containing spaces.\n\nExamples:\nluna-cli list archive.zip\nluna-cli pack-zip source -o output.zip\nluna-cli pack-7z source -o output.7z --solid on\nluna-cli pack-targz source -o output.tar.gz\nluna-cli test archive.zip\nluna-cli extract-here archive.zip -o destination\n\nPassword-capable commands accept -p followed by the password; command-line arguments can be visible to local process inspection or shell history. Use the desktop password dialog when you want to avoid entering a secret in command arguments. pack-targz with -p creates the encrypted .tar.gz.7z wrapper. Shell registration changes user configuration and is explicit.", "create", "passwords", "shell"))
    };
    public static IReadOnlyList<HelpTopic> All { get; } = Contents.SelectMany(Flatten).ToArray();
    private static IEnumerable<HelpTopic> Flatten(HelpTopic topic) => new[] { topic }.Concat(topic.Children.SelectMany(Flatten));
}
